import json
from pathlib import Path

DATA_PATH = Path(__file__).resolve().parent / 'data' / 'windows_command_registry.json'

def build_catalog():
    items = []

    def add(exe, cat, code, purpose, access, priv, danger, tier, plane,
            ps=None, wmi=None, win32=None, nt=None, com=None, etw=None, evtx=None,
            unattended=True, monitor=False, modify=False, gui=False, msc=False, cpl=False, builtin=False,
            etw_pipe=False, usn=False, templates=None, subcommands=None, sub_tree=None, route=None, tags=None):
        clean_name = exe.lower().replace('.exe', '').replace('.com', '').replace('.msc', '').replace('.cpl', '').replace(':', '')
        items.append({
            "executable": exe,
            "category": cat,
            "category_code": code,
            "purpose": purpose,
            "access_type": access,
            "required_privileges": priv,
            "danger_level": danger,
            "telemetry_tier": tier,
            "primary_control_plane": plane,
            "powershell_equivalent": ps,
            "wmi_cim_equivalent": wmi,
            "native_api_equivalent": win32,
            "native_nt_api_equivalent": nt,
            "com_equivalent": com,
            "etw_provider_equivalent": etw,
            "event_log_channel_equivalent": evtx,
            "can_run_unattended": unattended,
            "can_monitor": monitor,
            "can_modify_system": modify,
            "is_gui": gui,
            "is_msc_console": msc,
            "is_cpl_applet": cpl,
            "is_cmd_builtin": builtin,
            "etw_pipeline_enabled": etw_pipe,
            "usn_journal_enabled": usn,
            "command_templates": templates or [],
            "subcommands_info": subcommands or {},
            "subcommands_tree": sub_tree or {},
            "rest_endpoint": route or f"/api/v1/system32/tool/{clean_name}",
            "tags": tags or []
        })

    # 01. SHELLS & COMMAND EXECUTION
    add("cmd.exe", "shells_execution", "01. SHELLS & COMMAND EXECUTION", "Интерпретатор командной строки Windows (Command Prompt).", "READ_WRITE", "STANDARD", "HIGH", "CONTROL", "CLI", ps="Invoke-Expression / Start-Process", wmi="Win32_Process.Create", win32="CreateProcessW", nt="NtCreateUserProcess", templates=["cmd.exe /c \"{cmd}\""], tags=["shell", "cli", "batch"])
    add("powershell.exe", "shells_execution", "01. SHELLS & COMMAND EXECUTION", "Среда объектного сценария и автоматизации Windows PowerShell 5.1.", "READ_WRITE", "STANDARD", "HIGH", "CONTROL", "POWERSHELL", ps="Internal Engine", win32="System.Management.Automation", templates=["powershell.exe -NoProfile -ExecutionPolicy Bypass -Command \"{cmd}\""], tags=["powershell", "automation"])
    add("pwsh.exe", "shells_execution", "01. SHELLS & COMMAND EXECUTION", "Современный кроссплатформенный PowerShell Core 7+.", "READ_WRITE", "STANDARD", "HIGH", "CONTROL", "POWERSHELL", ps="Internal Engine", templates=["pwsh.exe -NoProfile -Command \"{cmd}\""], tags=["pwsh", "powershell7"])
    add("wscript.exe", "shells_execution", "01. SHELLS & COMMAND EXECUTION", "Оконный исполнитель скриптов Windows Script Host (VBScript/JScript).", "READ_WRITE", "STANDARD", "MEDIUM", "CONTROL", "COM", com="WScript.Shell", gui=True, templates=["wscript.exe \"{script_file}\""], tags=["wscript", "vbs", "js"])
    add("cscript.exe", "shells_execution", "01. SHELLS & COMMAND EXECUTION", "Консольный исполнитель скриптов Windows Script Host (CLI).", "READ_WRITE", "STANDARD", "MEDIUM", "CONTROL", "CLI", com="WScript.Shell", templates=["cscript.exe //NoLogo \"{script_file}\""], tags=["cscript", "vbs", "js"])
    add("mshta.exe", "shells_execution", "01. SHELLS & COMMAND EXECUTION", "Исполнитель HTML-приложений (Microsoft HTML Application Host).", "READ_WRITE", "STANDARD", "HIGH", "CONTROL", "GUI_MMC_CPL", gui=True, templates=["mshta.exe \"{hta_url_or_file}\""], tags=["hta", "html"])
    add("rundll32.exe", "shells_execution", "01. SHELLS & COMMAND EXECUTION", "Запуск экспортируемых Win32 DLL функций из командной строки.", "READ_WRITE", "STANDARD", "HIGH", "CONTROL", "WIN32_API", win32="LoadLibraryW + GetProcAddress", templates=["rundll32.exe {dll},{entry_point}"], tags=["dll", "rundll32"])
    add("regsvr32.exe", "shells_execution", "01. SHELLS & COMMAND EXECUTION", "Регистрация и дерегистрация OLE/COM серверов и элементов управления DLL/OCX.", "WRITE", "ADMINISTRATOR", "HIGH", "ADMIN", "COM", win32="DllRegisterServer / DllUnregisterServer", modify=True, templates=["regsvr32.exe /s \"{dll_path}\"", "regsvr32.exe /u /s \"{dll_path}\""], tags=["com", "dll-registration"])
    add("where.exe", "shells_execution", "01. SHELLS & COMMAND EXECUTION", "Поиск местоположения исполняемых файлов по системному PATH.", "READ", "STANDARD", "SAFE", "OBSERVE", "CLI", ps="Get-Command {cmd} | Select-Object -ExpandProperty Source", monitor=True, templates=["where.exe {pattern}"], tags=["search", "path", "discovery"])
