    add("icacls.exe", "files_directories", "02. FILES & DIRECTORIES", "Управление списками управления доступом ACL к файлам и папкам.", "READ_WRITE", "ADMINISTRATOR", "HIGH", "ADMIN", "WIN32_API", ps="Get-Acl / Set-Acl", win32="GetNamedSecurityInfoW / SetNamedSecurityInfoW", modify=True, subcommands={"/grant": "Предоставление прав", "/deny": "Запрет прав", "/save": "Бэкап ACL", "/restore": "Восстановление ACL"}, templates=["icacls.exe \"{path}\" /grant {user}:F", "icacls.exe \"{path}\" /save acl_backup.txt"], tags=["acl", "security", "permissions"])
    add("takeown.exe", "files_directories", "02. FILES & DIRECTORIES", "Смена владельца файла или директории на текущего пользователя или администраторов.", "WRITE", "ADMINISTRATOR", "HIGH", "ADMIN", "WIN32_API", ps="Set-Acl -Owner", win32="SetNamedSecurityInfoW(OWNER_SECURITY_INFORMATION)", modify=True, templates=["takeown.exe /f \"{path}\" /r /d y"], tags=["takeown", "ownership", "security"])
    add("robocopy.exe", "files_directories", "02. FILES & DIRECTORIES", "Надежное многопоточное копирование файлов и структуры каталогов (Robust File Copy).", "READ_WRITE", "STANDARD", "LOW", "CONTROL", "WIN32_API", ps="Copy-Item", win32="CopyFileExW", modify=True, templates=["robocopy.exe \"{src}\" \"{dst}\" /MIR /R:2 /W:5 /MT:16 /LOG:copy.log"], tags=["backup", "copy", "robocopy", "sync"])
