    add("findstr.exe", "files_directories", "02. FILES & DIRECTORIES", "Поиск строк и регулярных выражений в файлах и потоках текста (Grep для Windows).", "READ", "STANDARD", "SAFE", "OBSERVE", "CLI", ps="Select-String", monitor=True, templates=["findstr.exe /s /i /n \"{pattern}\" *.*"], tags=["grep", "search", "regex"])
    add("makecab.exe", "archiving_packaging", "47. ARCHIVING / PACKAGING", "Архиватор Microsoft Cabinet (.cab).", "WRITE", "STANDARD", "LOW", "CONTROL", "CLI", modify=True, templates=["makecab.exe \"{src}\" \"{dst}.cab\""], tags=["cab", "compression", "archive"])
