    add("extrac32.exe", "archiving_packaging", "47. ARCHIVING / PACKAGING", "Графический и консольный инструмент извлечения CAB архивов.", "READ_WRITE", "STANDARD", "LOW", "CONTROL", "CLI", modify=True, templates=["extrac32.exe /Y /E \"{cab_file}\""], tags=["cab", "extrac32"])

