    add("diskpart.exe", "storage_disks", "03. STORAGE / DISKS", "Низкоуровневое управление дисками, разметкой GPT/MBR, разделами, томами и VHD.", "READ_WRITE", "ADMINISTRATOR", "CRITICAL", "DESTRUCTIVE", "CLI", ps="Get-Disk / Initialize-Disk / New-Partition / Format-Volume", wmi="MSFT_Disk / MSFT_Partition / MSFT_Volume", win32="DeviceIoControl(IOCTL_DISK_*)", com="IVdsService", modify=True, subcommands={"list disk": "Список физических дисков", "list volume": "Список томов", "select disk": "Выбор диска", "clean": "Полное стирание разметки", "create partition": "Создание раздела", "format": "Форматирование тома", "attach vdisk": "Монтирование виртуального диска VHD", "compact vdisk": "Сжатие VHD"}, sub_tree={"disk": ["list", "select", "clean", "convert gpt", "convert mbr", "detail", "offline", "online"], "partition": ["list", "select", "create primary", "create efi", "delete", "extend", "shrink"], "volume": ["list", "select", "format", "assign", "remove", "detail"], "vdisk": ["attach", "detach", "compact", "expand", "merge"]}, templates=["diskpart.exe /s \"{script_file}\""], tags=["storage", "disk", "partition", "vhd", "gpt"])
    add("fsutil.exe", "storage_disks", "03. STORAGE / DISKS", "Расширенное управление параметрами NTFS, журналом изменений USN, квотами, TRIM и томами.", "READ_WRITE", "ADMINISTRATOR", "MEDIUM", "CONTROL", "CLI", ps="Get-Volume / Set-Volume", win32="FSCTL_* APIs", modify=True, monitor=True, usn=True, subcommands={"fsinfo": "Сведения о файловой системе", "usn": "Управление NTFS USN журналом", "behavior": "Настройка TRIM и генерации 8.3", "dirty": "Проверка dirty bit тома", "volume": "Управление томами и свободным местом", "quota": "Квоты диска"}, sub_tree={"fsinfo": ["drives", "drivetype", "volumeinfo", "ntfsinfo", "statistics"], "usn": ["queryjournal", "createjournal", "deletejournal", "readjournal", "enumnodata"], "behavior": ["query DisableDeleteNotify", "set DisableDeleteNotify 0", "query disable8dot3"], "dirty": ["query", "set"]}, templates=["fsutil.exe fsinfo volumeinfo {drive}:", "fsutil.exe usn queryjournal {drive}:", "fsutil.exe behavior query DisableDeleteNotify"], tags=["ntfs", "usn-journal", "trim", "filesystem", "telemetry"])
