    add("chkntfs.exe", "storage_disks", "03. STORAGE / DISKS", "Управление автоматической проверкой файловой системы при загрузке системы.", "READ_WRITE", "ADMINISTRATOR", "MEDIUM", "CONTROL", "WIN32_API", modify=True, templates=["chkntfs.exe {drive}:", "chkntfs.exe /x {drive}:"], tags=["chkntfs", "boot-check", "dirty-bit"])
